#include <stdio.h>
/*
 * ex02：主析取范式（Σm）与主合取范式（ΠM）
 * 为什么：同一个公式的「标准形式」是唯一的，这是机器判等、化简、SAT 编码的地基。
 * 本例用 f = (p∧q) ∨ (¬p∧r)：先枚举真值表，再按「成真赋值 -> 小项」拼 Σm，
 * 按「成假赋值 -> 极大项」拼 ΠM，最后把两种范式都打印成可读公式。
 */
static int f(int p, int q, int r) { return (p && q) || ((!p) && r); }

/* 打印小项：变量取 1 写本身，取 0 写否定 */
static void print_minterm(int idx, int n) {
    printf("(");
    for (int i = 0; i < n; i++) {
        int bit = (idx >> (n - 1 - i)) & 1;      /* 高位对应第一个变量 */
        const char *name = (i == 0) ? "p" : (i == 1) ? "q" : "r";
        if (i) printf("^");
        printf("%s%s", bit ? "" : "~", name);
    }
    printf(")");
}

/* 打印极大项：变量取 0 写本身，取 1 写否定；整体再取反 */
static void print_maxterm(int idx, int n) {
    printf("(");
    for (int i = 0; i < n; i++) {
        int bit = (idx >> (n - 1 - i)) & 1;
        const char *name = (i == 0) ? "p" : (i == 1) ? "q" : "r";
        if (i) printf("v");
        printf("%s%s", bit ? "~" : "", name);
    }
    printf(")");
}

int main(void) {
    int mins[8], maxs[8], nm = 0, nx = 0;
    printf("p q r | f\n------+--\n");
    for (int v = 0; v < 8; v++) {
        int p = (v >> 2) & 1, q = (v >> 1) & 1, r = v & 1;
        int y = f(p, q, r);
        printf("%d %d %d | %d\n", p, q, r, y);
        if (y) mins[nm++] = v; else maxs[nx++] = v;
    }
    printf("\nPrincipal DNF  = S m{");
    for (int i = 0; i < nm; i++) printf("%s%d", i ? "," : "", mins[i]);
    printf("}\n             = ");
    for (int i = 0; i < nm; i++) { if (i) printf(" v "); print_minterm(mins[i], 3); }
    printf("\n\nPrincipal CNF  = P M{");
    for (int i = 0; i < nx; i++) printf("%s%d", i ? "," : "", maxs[i]);
    printf("}\n             = ");
    for (int i = 0; i < nx; i++) { if (i) printf(" ^ "); print_maxterm(maxs[i], 3); }
    printf("\n\nnote: |models| = %d, |non-models| = %d, 2^3 = 8\n", nm, nx);
    printf("      minterm count + maxterm count always equals 2^n.\n");
    return 0;
}
